import { execSync } from 'child_process';
import { createHmac, createHash } from 'crypto';

const RENDER_KEY = 'rnd_1H0XCquMZQTRyAnHgbEv8dVWYPVs';
const API_SVC = 'srv-d7t9ivreo5us73ftose0';

function fetchEnvVarRaw(name) {
  const cmd = `curl -sS -m 10 -H "Authorization: Bearer ${RENDER_KEY}" "https://api.render.com/v1/services/${API_SVC}/env-vars/${name}"`;
  const out = execSync(cmd, { encoding: 'utf-8' });
  const d = JSON.parse(out);
  const ev = d.envVar || d;
  return ev.value || '';
}

const accessKeyRaw = fetchEnvVarRaw('AWS_ACCESS_KEY_ID');
const secretKeyRaw = fetchEnvVarRaw('AWS_SECRET_ACCESS_KEY');
const regionRaw = fetchEnvVarRaw('AWS_REGION') || 'us-east-1';

// Don't trim - check raw values
const accessKey = accessKeyRaw.trim();
const secretKey = secretKeyRaw.trim();
const region = regionRaw.trim();

console.log('=== RAW AUDIT ===');
console.log('ACCESS_KEY_ID raw len:', accessKeyRaw.length, 'trimmed len:', accessKey.length);
console.log('ACCESS_KEY_ID value:', accessKey);
console.log('SECRET_ACCESS_KEY raw len:', secretKeyRaw.length, 'trimmed len:', secretKey.length);
console.log('SECRET raw first 4:', secretKey.substring(0, 4));
console.log('SECRET raw last 4:', secretKey.slice(-4));
console.log('SECRET has \\r:', secretKeyRaw.includes('\r'));
console.log('SECRET has \\n:', secretKeyRaw.includes('\n'));
console.log('SECRET has \\t:', secretKeyRaw.includes('\t'));
console.log('SECRET char codes:', JSON.stringify([...secretKey].map(c => c.charCodeAt(0))));
console.log('REGION:', region);

// Test with AWS CLI if available
console.log('\n=== Test via AWS CLI (if available) ===');
try {
  const env = {
    ...process.env,
    AWS_ACCESS_KEY_ID: accessKey,
    AWS_SECRET_ACCESS_KEY: secretKey,
    AWS_REGION: region,
    AWS_DEFAULT_REGION: region,
  };
  const result = execSync('aws s3 ls s3://ivxholding.com/apk/ --region us-east-1 2>&1 || echo "AWS_CLI_NOT_AVAILABLE"', {
    encoding: 'utf-8',
    env,
    timeout: 15000,
  });
  console.log('AWS CLI result:', result.substring(0, 300));
} catch (e) {
  console.log('AWS CLI error:', e.message.substring(0, 300));
}

// Test 1: GetBucketLocation with path-style
console.log('\n=== Test 1: GetBucketLocation (path-style, us-east-1) ===');
const host1 = 's3.us-east-1.amazonaws.com';
const bucket = 'ivxholding.com';
const now1 = new Date();
const amzDate1 = now1.toISOString().replace(/[:.-]/g, '').replace(/\d{3}Z$/, 'Z');
const dateStamp1 = amzDate1.substring(0, 8);
const payloadHash1 = createHash('sha256').update('').digest('hex');
const canonicalHeaders1 = `host:${host1}\nx-amz-content-sha256:${payloadHash1}\nx-amz-date:${amzDate1}\n`;
const signedHeaders1 = 'host;x-amz-content-sha256;x-amz-date';
const canonicalRequest1 = ['GET', `/${bucket}`, 'location=', canonicalHeaders1, signedHeaders1, payloadHash1].join('\n');
const canonicalHash1 = createHash('sha256').update(canonicalRequest1).digest('hex');
const credentialScope1 = `${dateStamp1}/us-east-1/s3/aws4_request`;
const stringToSign1 = ['AWS4-HMAC-SHA256', amzDate1, credentialScope1, canonicalHash1].join('\n');
const kDate1 = createHmac('sha256', 'AWS4' + secretKey).update(dateStamp1).digest();
const kRegion1 = createHmac('sha256', kDate1).update('us-east-1').digest();
const kService1 = createHmac('sha256', kRegion1).update('s3').digest();
const kSigning1 = createHmac('sha256', kService1).update('aws4_request').digest();
const signature1 = createHmac('sha256', kSigning1).update(stringToSign1).digest('hex');
const authHeader1 = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope1}, SignedHeaders=${signedHeaders1}, Signature=${signature1}`;
const url1 = `https://${host1}/${bucket}?location=`;
try {
  const resp1 = execSync(`curl -sS -m 15 -w "\\nHTTP:%{http_code}" -H "Authorization: ${authHeader1}" -H "x-amz-content-sha256: ${payloadHash1}" -H "x-amz-date: ${amzDate1}" "${url1}"`, { encoding: 'utf-8' });
  console.log(resp1.substring(0, 400));
} catch (e) {
  console.log('Error:', e.message.substring(0, 400));
}

// Test 2: ListObjectsV2 with virtual-hosted style
console.log('\n=== Test 2: ListObjectsV2 (virtual-hosted, us-east-1) ===');
const host2 = 'ivxholding.com.s3.us-east-1.amazonaws.com';
const amzDate2 = new Date().toISOString().replace(/[:.-]/g, '').replace(/\d{3}Z$/, 'Z');
const dateStamp2 = amzDate2.substring(0, 8);
