const signedHeaders2 = 'host;x-amz-content-sha256;x-amz-date';
const canonicalRequest2 = ['GET', '/', 'list-type=2&prefix=apk%2F&max-keys=5', canonicalHeaders2, signedHeaders2, payloadHash2].join('\n');
const canonicalHash2 = createHash('sha256').update(canonicalRequest2).digest('hex');
const credentialScope2 = `${dateStamp2}/us-east-1/s3/aws4_request`;
const stringToSign2 = ['AWS4-HMAC-SHA256', amzDate2, credentialScope2, canonicalHash2].join('\n');
const kDate2 = createHmac('sha256', 'AWS4' + secretKey).update(dateStamp2).digest();
const kRegion2 = createHmac('sha256', kDate2).update('us-east-1').digest();
const kService2 = createHmac('sha256', kRegion2).update('s3').digest();
const kSigning2 = createHmac('sha256', kService2).update('aws4_request').digest();
const signature2 = createHmac('sha256', kSigning2).update(stringToSign2).digest('hex');
const authHeader2 = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope2}, SignedHeaders=${signedHeaders2}, Signature=${signature2}`;
const url2 = `https://${host2}/?list-type=2&prefix=apk%2F&max-keys=5`;
try {
  const resp2 = execSync(`curl -sS -m 15 -w "\\nHTTP:%{http_code}" -H "Authorization: ${authHeader2}" -H "x-amz-content-sha256: ${payloadHash2}" -H "x-amz-date: ${amzDate2}" "${url2}"`, { encoding: 'utf-8' });
  console.log(resp2.substring(0, 500));
} catch (e) {
  console.log('Error:', e.message.substring(0, 400));
}

// Test 3: Check if bucket is in a different region (us-west-2, eu-west-1)
console.log('\n=== Test 3: Try us-west-2 region ===');
const host3 = 's3.us-west-2.amazonaws.com';
const amzDate3 = new Date().toISOString().replace(/[:.-]/g, '').replace(/\d{3}Z$/, 'Z');
const dateStamp3 = amzDate3.substring(0, 8);
const canonicalHeaders3 = `host:${host3}\nx-amz-content-sha256:${payloadHash1}\nx-amz-date:${amzDate3}\n`;
const canonicalRequest3 = ['GET', `/${bucket}`, 'location=', canonicalHeaders3, signedHeaders1, payloadHash1].join('\n');
const canonicalHash3 = createHash('sha256').update(canonicalRequest3).digest('hex');
const credentialScope3 = `${dateStamp3}/us-west-2/s3/aws4_request`;
const stringToSign3 = ['AWS4-HMAC-SHA256', amzDate3, credentialScope3, canonicalHash3].join('\n');
const kDate3 = createHmac('sha256', 'AWS4' + secretKey).update(dateStamp3).digest();
const kRegion3 = createHmac('sha256', kDate3).update('us-west-2').digest();
const kService3 = createHmac('sha256', kRegion3).update('s3').digest();
const kSigning3 = createHmac('sha256', kService3).update('aws4_request').digest();
const signature3 = createHmac('sha256', kSigning3).update(stringToSign3).digest('hex');
const authHeader3 = `AWS4-HMAC-SHA256 Credential=${accessKey}/${credentialScope3}, SignedHeaders=${signedHeaders1}, Signature=${signature3}`;
const url3 = `https://${host3}/${bucket}?location=`;
try {
  const resp3 = execSync(`curl -sS -m 15 -w "\\nHTTP:%{http_code}" -H "Authorization: ${authHeader3}" -H "x-amz-content-sha256: ${payloadHash1}" -H "x-amz-date: ${amzDate3}" "${url3}"`, { encoding: 'utf-8' });
  console.log(resp3.substring(0, 400));
} catch (e) {
  console.log('Error:', e.message.substring(0, 400));
}

// Test 4: Anonymous GET to check bucket region
console.log('\n=== Test 4: Anonymous HEAD bucket to detect region ===');
try {
  const resp4 = execSync(`curl -sS -m 10 -w "\\nHTTP:%{http_code}" -I "https://s3.us-east-1.amazonaws.com/ivxholding.com/" 2>&1`, { encoding: 'utf-8' });
